const withWikiPlacedSprite = (item: StorageItemDefinition): StorageItemDefinition => {
  const placementImageUrl = wikiPlacedSpriteById[item.id];
  return placementImageUrl
    ? { ...item, placementImageUrl, renderAtNativeScale: true }
    : item;
};

